export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, ta = u / g, H = u * u / (2 * g);
  const t = sdk.clamp(time, 0, T);
  const y = u * t - g * t * t / 2;
  const v = u - g * t;
  const eps = 1e-9;
  let st = 'Ready to toss';
  if (t <= 0) st = 'Ready to toss';
  else if (t >= T - eps) st = 'Back at launch height';
  else if (Math.abs(t - ta) < 0.005) st = 'At the top';
  else if (t < ta) st = 'Rising'; else st = 'Falling';
  const F = m * g;
  const o = [];
  o.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 34, w: 300, h: 376, title: 'The motion', state: st }));
  o.push(...sdk.panel({ id: 'lane.graph', x: 330, y: 34, w: 300, h: 376, title: 'Velocity over time', state: 'v = u - g t' }));
  const y0 = 385, y1 = 100;
  const py = h => y0 - (h / 2.2) * (y0 - y1);
  o.push(sdk.axis('axis.h', { x: 60, y: y0, length: y0 - y1, orientation: 'y', min: 0, max: 2.2, ticks: [0, 0.5, 1, 1.5, 2], label: 'Height', unit: 'm' }));
  const by = py(y), bx = 150;
  o.push(sdk.circle('ball.toss', bx, by, 28, {}));
  o.push(...sdk.vector('vec.v', { x: bx, y: by }, { value: v, direction: 'up' }, { scale: 14, label: 'v', role: 'observed' }));
  o.push(...sdk.vector('vec.a', { x: bx + 40, y: by }, { value: -g, direction: 'up' }, { scale: 6, label: 'a', role: 'warning' }));
  o.push(...sdk.callout(215, 150, ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s²', 'F = ' + sdk.format(F, 1) + ' N down'], { id: 'callout.toss' }));
  const pts = (a, b) => { const r = []; for (let i = 0; i <= 8; i++) { const s = a + (b - a) * i / 8; r.push({ x: s, y: u - g * s }); } return r; };
  const series = [{ label: 'v up to now', kind: 'line', points: t > 0 ? pts(0, t) : [{ x: 0, y: u }, { x: 0.001, y: u - g * 0.001 }] }];
  const s0 = Math.max(0, t - 0.1), s1 = Math.min(T, t + 0.1);
  series.push({ label: 'slope a = -g', kind: 'line', points: [{ x: s0, y: u - g * s0 }, { x: s1, y: u - g * s1 }] });
  series.push({ label: 'continuation', kind: 'line', points: pts(t, T) });
  o.push(sdk.plot('plot.vt', { x: 345, y: 80, w: 275, h: 300, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' } }, series }));
  return { frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st }] }, quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: ta, apexHeight: H, height: y, velocity: v, acceleration: -g, force: F, velocity_: v } };
}
